  PanelText_UI_Events_2ndAnnivWB_StageGroup_Text_C_Introduction_Content = {
    Text = "এসো! উন্মাদনা, রক্তপাতে ভেজা হত্যাযজ্ঞ আর যন্ত্রণাকে সুর করে, আমরা তারকাদের ভিড়ে ঝলমল করা এই রেকুইয়েম গেয়ে উঠি!\nও সেই অন্ধ মূর্খ দেবতা, বোকামি ও বিশৃঙ্খলার সর্বোচ্চ সত্তা, যেন জাগরণ না ঘটে—না এখন, না কোনো ভবিষ্যতে।"
  },
  PanelText_UI_Events_2ndAnnivWB_StageGroup_Text_C_Title_Content = {
    Text = "তারকা রিকুইয়েম"
  },
  PanelText_UI_Events_Activity_StageGroup_Text_C_Introduction_Content = {
    Text = "দেবতার প্রতিশ্রুত সময় ঘনিয়ে এসেছে।\nহাজার হাজার বছরের প্রতীক্ষা আনন্দময় পরিসমাপ্তির দ্বারপ্রান্তে, প্রতিশ্রুত ভূমি সমুদ্র থেকে জেগে উঠবে।\nদেবতা দেবমাতার বক্ষ থেকে পুনর্জন্ম নেবেন, সপ্তম দিনের সমাপ্তিতে নতুন জগৎ অবতীর্ণ হবে।"
