  },
  PanelText_UI_Events_OceanBoss_StageGroup_Text_C_Introduction_Content = {
    Text = "তোমার দেহ ত্যাগ করো, তোমার প্রজ্ঞা ত্যাগ করো, আর এই বিশুদ্ধ ইচ্ছার জগতে অনুভব করো তাঁর উপস্থিতি।\nতিনি তোমার একমাত্র। তিনিই তোমার সর্বস্ব।"
  },
  PanelText_UI_Events_OceanBoss_StageGroup_Text_C_Title_Content = {
    Text = "বিষণ্ণ জোয়ার"
  },
  PanelText_UI_Events_OriHelot_StageGroup_Text_C_Introduction_Content = {
    Text = "\nমুখ বড় করে খোলো, আর দাঁত বসাও নির্মমভাবে।\nগ্রাস করা, নাকি গ্রাস হওয়া—এই নিয়মেই চলে যুদ্ধ, এই নিয়তিই এক জন্তুর ভাগ্য।"
  },
  PanelText_UI_Events_OriHelot_StageGroup_Text_C_Resonance_Content = {
