  PanelText_UI_Events_Panel_ActivityPassport_Text_C_Ordinary_Content = {
    Text = "সাধারণ আর্কাইভস"
  },
  PanelText_UI_Events_Panel_ActivityPassport_Text_C_PassportUp_Content = {
    Text = "উন্নয়ন অর্জন"
  },
  PanelText_UI_Events_Panel_ActivityPassport_Text_C_Senior_Content = {
    Text = "প্রিমিয়াম আর্কাইভস"
  },
  PanelText_UI_Events_Panel_ActivityPassport_Text_C_illustrate_Content = {
    Text = "ইভেন্টের বিবরণ"
  },
  PanelText_UI_Events_Panel_ActivityPassport_Text_PayTip_Content = {
    Text = "প্রদর্শিত মূল্য কেবলমাত্র রেফারেন্সের জন্য। প্রকৃত অর্থপ্রদান প্রযোজ্য মুদ্রায়, বর্তমান বিনিময় হারে সম্পন্ন হবে।"
  },
  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Introduction_Content = {
    Text = "আলো জ্বলে উঠল। করতালি থামল। দর্শকরা অপেক্ষা করছে।\nমঞ্চে ওঠার সময় হয়েছে, আমার প্রিয় সন্তানেরা। যাও মঞ্চে ওঠো, অভিনয় করো, তোমাদের হৃদয় ছিঁড়ে ফেলো, তোমাদের গভীরতম গোপনীয়তা বিক্রি করো। তোমাদের সবচেয়ে ভয়াবহ ক্ষত দিয়ে মানুষের আনন্দের মিষ্টান্ন তৈরি করো। লোভের সাথে মঞ্চের সেই আলো উপভোগ করো যা শুধু তোমার জন্যই জ্বলেছে, যতক্ষণ না পর্দা তোমাকে ও দর্শকদের একসাথে সমাহিত করে।\nএটা তোমাদের ভাগ্যনির্ধারিত মঞ্চ, এতে ওঠো! ভয় পেও না, সংকোচ করো না।"
  },
  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Resonance_Content = {
    Text = "অনুরণন"
  },
  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Title_Content = {
