  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Introduction_Content = {
    Text = "♪~~♫~~♪~~♫~~♪~~♫~~\nতুষারাবৃত পর্বতের নিচে, সকল পথপ্রদর্শক এটি মনে রাখে, সকল শিশু এটি গেয়ে বেড়ায়। তিনি সুউচ্চ তুষার পর্বতের ইচ্ছার মূর্তিমান রূপ, তিনি করুণাময়ী দেবী উমাপতি।\nতাঁর দৈব শক্তি মানবজগতে ছড়িয়ে পড়েছে, তাঁর ধনসম্পদ খুঁজে পাওয়া যায় না, সেগুলো একেবারে কাছেই আছে, আবার সেগুলো কোথাও নেই। কিছু একটা ছেড়ে দাও, কিছু একটা আঁকড়ে ধরো।\nযে দেবীর প্রকৃত সত্তার প্রতি আন্তরিক নয়, সে মৃত তুষার পর্বতের সাথে চিরতরে তুষার পর্বতের গভীরে সমাহিত হবে।"
  },
  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Resonance_Content = {
    Text = "অনুরণন"
  },
  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Title_Content = {
