  PanelText_UI_Events_Panel_Castor_StageGroup_Text_C_Introduction_Content = {
    Text = "পাখির জীবন মানেই স্বাধীনতার জীবন। ডিম ফোটার সেই ক্ষণে তোমার তা দেখা উচিত ছিল—মৃত্যুর হাত থেকে জীবন নামের স্বাধীনতা ছিনিয়ে আনার সেই লড়াই। প্রথম উড়তে শেখার সময়ও তোমার দেখা উচিত ছিল—উষ্ণ বাসার আরামের হাত থেকে বেঁচে থাকার স্বাধীনতা ছিনিয়ে নেওয়ার সেই মুহূর্ত। এখন, যদি স্বাধীনতার চাবিটি মৃত্যুর অতল গহ্বরে নিক্ষিপ্ত হয়, সে এক মুহূর্ত দেরি না করে ঝাঁপিয়ে পড়বে—সঙ্কীর্ণ জীবনের বদলে মৃত্যুর উন্মত্ত ঝড়ের মুখোমুখি হওয়াকে বেছে নিয়ে, তার বদলে আলিঙ্গন করবে অসীম স্বাধীনতাকে।"
  },
