  PanelText_UI_Events_Panel_Clementine_StageGroup_Text_C_Introduction_Content = {
    Text = "সেই দিন থেকে, সে আর এক ফোঁটা অশ্রুও ফেলেনি।\nএকাকী ঘুরে বেড়ায়, নির্বাসিতদের ভরা এক জগতে ভেসে বেড়ায়।\nএক মহা পরিকল্পনা শুরু হতে চলেছে, তার চূড়ান্ত বিদায় হিসেবে।\nসে সর্বশ্রেষ্ঠ মনোবিজ্ঞানী, আর এটাই তার সবচেয়ে সফল চিকিৎসা।"
