  PanelText_UI_Events_Panel_ClotherLottery_Text_C_Tip_Content = {
    Text = "<color=#e3c96e>প্রিমিয়াম স্কিন</color> পড়ে যাওয়ার সম্ভাবনা শুরু হবে <color=#e3c96e>5</color>ম টান থেকে"
