  PanelText_UI_Events_Panel_ClotherLottery_Text_Free_Content = {
    Text = "বিনামূল্যে"
  },
  PanelText_UI_Events_Panel_Daffodil_StageGroup_Text_C_Introduction_Content = {
    Text = "এই সমুদ্রতীরবর্তী শহরে রয়েছে এক কোলাহলমুখর বাণিজ্যিক সড়ক। সমুদ্রবাণিজ্য এখানে এনে ফেলেছে অগণিত আধুনিক পণ্য; যথেষ্ট লিওনীয় ফ্লোরিন খরচ করতে পারলে, সন্তোষজনক কিছু না কিছু তুমি সবসময়ই খুঁজে পাবে।\nশুধু একটিই ব্যতিক্রম—মোড়ের কোণে ছোট্ট এক দোকান, পুরোনো দিনের আবহে ভরা, জাদুময় প্রাচীন সামগ্রীতে ঠাসা। ধোঁয়ায় ঢেকে থাকা পাইপের আড়াল থেকে, প্রশস্ত কিনারাওয়ালা টুপি পরা দোকানদার ধীরে ধীরে তোমার দিকে একটুখানি হাসি মেলে ধরবে।\n\"উদ্বেগহীন দোকানে স্বাগত জানাও, যেখানে তোমার সব চাহিদাই পূরণ হবে, যদি কেবল যথেষ্ট প্রতিদান তুমি দিতে পারো...\"\n\"অবশ্যই, অবশ্যই, দাম একেবারেই ন্যায্য, আর আমরা সকলে’র সঙ্গেই সৎ।\""
  },
