  },
  PanelText_UI_Events_Panel_KathiguRa_StageGroup_Text_C_Introduction_Content = {
    Text = "তিনি আবারও পৃথিবীর বুকে মাথা তুলে দাঁড়ালেন, সবকিছু ভস্মীভূত করার প্রতিশোধ প্রতিশ্রুতি মতোই এসে পড়ল।\n\nসেটা হলো অবিরাম শিকার, সেটা হলো দাহনের প্রভুর জ্বলন্ত আগুন।\n\nতিনি প্রতিটি কোণে পা রাখবেন, মৃত্যুর সাথে চুক্তিবদ্ধ সকলকে শিকার করবেন।\n\nপালাও, পালাও, আরও গভীর অন্ধকারে পালাও, যেখানে তোমরা মনে করো খুঁজে পাওয়া যাবে না সেখানে পালাও।\n\nযদিও এটা সম্পূর্ণ অর্থহীন, কারণ তিনি শেষ পর্যন্ত প্রতিটি জগৎ পেরিয়ে যাবেন।\n\nতিনি সবকিছু শিকার করবেন, যতক্ষণ না সব ছাইয়ের মতো ভস্মীভূত হয়।"
  },
