  PanelText_UI_Events_Panel_LotanCetarchon_StageGroup_Text_C_Introduction_Content = {
    Text = "শক্তি, ক্ষমতা, অর্থ, স্বাধীনতা… লেভিয়াথানের ভূমিতে, তিনি তোমাকে সব কিছু দেবেন যা তুমি চাও।\nশুধু, তোমাকে শেষ পর্যন্ত দাঁড়িয়ে থাকা মানুষটি হতে হবে।"
