  PanelText_UI_Events_Panel_Mosk_StageGroup_Text_C_Introduction_Content = {
    Text = "আকাশ~পরিষ্কার~সমুদ্র~শান্ত~\nমস্ক~বন্ধুরা~ছোট কয়লাবল~যাত্রা শুরু!\nঝড়, ভয় নেই, বিদ্যুৎ, ভয় নেই, মস্ক, বন্ধুরা, ছোট কয়লাবল~\nস্বাধীনতার জন্য, যা·ত্রা·শুরু!"
