  },
  PanelText_UI_Events_Panel_Mouchette_StageGroup_Text_C_Introduction_Content = {
    Text = "হঠাৎ একদিন, তুমি আবিষ্কার করলে যে তুমি আর আগের মতো নেই।\nকেউ এটা লক্ষ্য করেনি, কারণ তোমার আচরণ একই রকম, তোমার চেহারাও একই রকম উজ্জ্বল।\nকিন্তু তুমি ভালো করেই জানো, সেই একসময়ের রক্তলাল হৃদয়টি কুয়াশায় তৈরি একটি মুখোশে ঢেকে গেছে।\n「যদি আমি চিরকাল ছদ্মবেশ ধরে রাখতে পারি, তাহলে কি আমি এখনও আগের আমি?」\nশুভকামনা, এই প্রশ্নটি তোমার মস্তিষ্কে এক সেকেন্ডের বেশি থাকেনি, যাই হোক সেই মুখোশ খোলার আগে কেউ তোমার আসল চিন্তা জানতে পারবে না।\n「তাহলে, চলো রওনা দিই~」"
  },
