  PanelText_UI_Events_Panel_OriDoll_StageGroup_Text_C_Introduction_Content = {
    Text = "সে পৃথিবীর অন্তিম প্রান্তের মহাদ্বারের দিকে তাকিয়ে থাকে, তারপর বিন্দুমাত্র দ্বিধা না করে এগিয়ে যায়。\nক্লিক। হাতল ঘোরে। দোরগোড়ার ওপারে তার চোখ উন্মুখ হয়ে খোঁজে。\nকিন্তু সেখানে আছে কেবল শূন্যতা। সে পা বাড়িয়েছে মায়াস্বপ্নের ভেতর。\nতার বোঝা উচিত ছিল: যে দান বিনা মূল্যে আসে, তারই দাম সবচেয়ে বেশি চুকাতে হয়।"
