  PanelText_UI_Events_Panel_OriMurphy_StageGroup_Text_C_Introduction_Content = {
    Text = "দেবতার প্রতিশ্রুত সময় ঘনিয়ে এসেছে।\nহাজার হাজার বছরের প্রতীক্ষা আনন্দময় পরিসমাপ্তির দ্বারপ্রান্তে, প্রতিশ্রুত ভূমি সমুদ্র থেকে জেগে উঠবে।\nদেবতা দেবমাতার বক্ষ থেকে পুনর্জন্ম নেবেন, সপ্তম দিনের সমাপ্তিতে নতুন জগৎ অবতীর্ণ হবে।"
