  PanelText_UI_Events_Panel_Pickman_StageGroup_Text_C_Introduction_Content = {
    Text = "সুস্থতা আর ভাঙনের মাঝখানে, এক উদ্ভট পাণ্ডুলিপি খুলে যায়।\nযে বিভ্রমকে তুমি ঘৃণা কর, তা আঁকে দীপ্তিময় রঙ,\nযে নিয়ন্ত্রণহীনতাকে তুমি ভয় পাও, তা ধারণ করে আনুগত্যের রূপ।\nএখানে, উন্মাদনাই শিল্পের প্রবৃত্তি, বিশ্বের আদিম উৎস,\nএকমাত্র সত্য, যে কখনো মিথ্যা বলে না।"
