  PanelText_UI_Events_Panel_Pollux_StageGroup_Text_C_Introduction_Content = {
    Text = "সেই ঘৃণা ও ভালোবাসা, উষ্ণতা ও আঘাত, যা পেয়েছিলে ও যা হারিয়েছিলে, সব এতটাই জড়িয়ে গেছে যে আর আলাদা করা যায় না।\nআমাদের একই রক্ত বইতে দাও, তারা একত্রিত হয়ে আমাদের অবিচ্ছেদ্য ভাগ্য গড়ে তুলবে।"
