  PanelText_UI_Events_Panel_Pontos_StageGroup_Text_C_Introduction_Content = {
    Text = "যখন অশুভ সাদা আলো আবার উচ্চ শিকার টহলের জানালা ভেদ করে, সে তোমাকে আমন্ত্রণ জানিয়েছে।\nআলিঙ্গন, গ্রাস, আবেষ্টন, ভিড়…… \nসমুদ্রের গভীর থেকে আসা আহ্বানে সাড়া দাও, এই অবিরাম শিকার টহলে যোগ দাও, তোমার অতীত, তোমার সত্তা, সবকিছুই এখন আর গুরুত্বহীন।"
