  PanelText_UI_Events_Panel_Saya_StageGroup_Text_C_Introduction_Content = {
    Text = "বিজ্ঞান, গুরুত্বহীন।\nনীতিশাস্ত্র, গুরুত্বহীন।\nনৈতিকতা, গুরুত্বহীন।\nজীবন, মৃত্যু, আশা, হতাশা……শেষের শেষে, ভূগর্ভের নোটবুকে, দুটি ভিন্ন হাতের লেখায় একই অনুমান লেখা রয়েছে।\nতাঁরা বলেন: 「দেখো, ভালোবাসাই একমাত্র, চিরন্তন বিষয়।」"
