  PanelText_UI_Events_Panel_Sorel_StageGroup_Text_C_Introduction_Content = {
    Text = "বহু বছর পরে, এক জীবনীকার এক সন্ধ্যায় তার দরজায় কড়া নাড়ল।\nসেদিন তারা অনেক কথা বলেছিল, আগাত পাথর থেকে শুরু করে পচে যাওয়া গোলাপের প্রাসাদ পর্যন্ত...\nএখন, লেখক এই সব খণ্ডাংশ শব্দকে গ্রন্থে বেঁধেছে, এখানে উপস্থিত সকলে-র উদ্দেশে উৎসর্গ করে।"
  },
