  PanelText_UI_Events_Panel_StElmosFire_StageGroup_Text_C_Introduction_Content = {
    Text = "পুরোনো সেক্সট্যান্ট নক্ষত্রদের মধ্যকার কোণ নির্ধারণ করে, প্রাচীন সমুদ্র মানচিত্র আঁকে প্রত্যাশিত পথরেখা, আর ক্ষয়ে যাওয়া কম্পাস ঠিক করে দেয় সামনে এগোনোর দিক...\nঅন্তহীন, শীতল কৃষ্ণ সাগরের গভীরেও এখনো আছে অনুসন্ধানী, যারা সাধারণ তামা আর লোহায় ভরসা করে সকলের পথ দেখায়।\nসকল পথপ্রদর্শক যেন কোনোদিন পথ না হারায়।"
