  PanelText_UI_Events_Panel_Xu_StageGroup_Text_C_Introduction_Content = {
    Text = "ভালোবাসা থেকে জন্ম নেয় অভিযোগ, অভিযোগ থেকে জন্ম নেয় ঘৃণা, আঠালো, অবিরত, বিষণ্ণ……\nআকাশে ডাকলে সাড়া নেই, মাটিতে পালানোর পথ নেই, তাই রাতের কুয়াশায় লুকানো সেই হাসি তোমার আহ্বানে সাড়া দিল, তোমাকে কোনো মূল্য দিতে হবে না।\nতার দিকে তাকাও, তাকে অনুসরণ করো, তার সাথে মিশে যাও, তার হয়ে যাও।"
