  PanelText_UI_Events_RAID_StageGroup_Text_C_Introduction_Content = {
    Text = "কালো, কালো, কালো……\nঘন কালো দানবরা চিৎকার করছে, গর্জন করছে, উন্মত্ত নৃত্য করছে, জোয়ারের মতো তোমার দিকে ধেয়ে আসছে।\n 「পুচ্——」\n「এই সিলভার কোরে এত কম, পরের বার আরও বেশি নিয়ে আসতে মনে রেখো।」"
