    Text = "তদন্তের পুরস্কার"
  },
  PanelText_UI_Events_TeamSchool_StageGroup_Text_C_Introduction_Content = {
    Text = "কালো, কালো জোয়ার অবিরাম উচ্ছ্বাস তোলে।\nউন্মত্ত বিড়ালগুলো আপনাকে ঘিরে ধরেছে, অসংখ্য মাত্রা থেকে ছুটে আসছে আপনার দিকে।"
