  },
  PanelText_UI_Events_WorldBoss_StageGroup_Text_C_Introduction_Content = {
    Text = "তোমার আদিমতম হতাশার মুখোমুখি হও। তোমার আদিমতম আতঙ্কের মুখোমুখি হও। \nঅদৃশ্যভাবে পাশাপাশি দাঁড়াও, তারপর তাঁকে পরাস্ত করো।"
